const body = $('POST /coach').first().json.body || {};
const LANGS = { en: { name: 'English', dir: 'ltr', disclosure: 'This is an AI-generated message, not financial advice.' }, ar: { name: 'Arabic', dir: 'rtl', disclosure: 'هذه رسالة من الذكاء الاصطناعي، وليست نصيحة مالية.' } };
const language = LANGS[body.language] ? body.language : 'en';
const SIGNPOSTS = { stepchange: { name: 'StepChange', url: 'https://www.stepchange.org', why: 'Free debt advice' }, citizens_advice: { name: 'Citizens Advice', url: 'https://www.citizensadvice.org.uk', why: 'Free help with bills, benefits and rent' }, moneyhelper: { name: 'MoneyHelper', url: 'https://www.moneyhelper.org.uk', why: 'Free, government-backed money guidance' } };
const f = $('Forecast').first().json;
const fm = $('Forecast with monthly insurance').first().json;
const INST = 62;
const name = (f.persona && f.persona.name) || 'Adam';
const risk = (body.risk && body.risk.shortfall) ? body.risk : (f.risks[0] || null);
const monthOf = (d) => new Date(d + 'T00:00:00Z').toLocaleString('en-GB', { month: 'long', timeZone: 'UTC' });
const billAmount = (n) => { const from = new Date(Date.parse(risk.week + 'T00:00:00Z') - 3 * 864e5).toISOString().slice(0, 10); let fb = null; for (const d of f.days) for (const e of d.events) if (e.name === n && e.amount < 0) { const hit = { name: n, amount: -e.amount, date: d.date }; if (d.date >= from && d.date <= risk.firstDay) return hit; if (!fb) fb = hit; } return fb || { name: n }; };
const OPTIONS = {};
if (risk) {
  OPTIONS.save_weekly = { id: 'save_weekly', title: risk.fix, effect: (risk.saveWeekly * risk.weeksUntil >= risk.shortfall) ? 'covers the £' + risk.shortfall + ' gap' : 'makes the gap smaller', apply: null };
  const rm = (fm.risks || [])[0];
  OPTIONS.monthly_insurance = { id: 'monthly_insurance', title: 'Ask the insurer to let you pay the car insurance monthly (about £' + INST + ' a month, usually a bit dearer overall)', effect: rm ? 'the gap shrinks from £' + risk.shortfall + ' to £' + rm.shortfall : 'no short week at all', apply: { billChanges: { 'Car insurance (annual)': INST } } };
}
const facts = { name, today: f.today, current_balance: Math.round(f.currentBalance), income_typical_week: Math.round(f.income.typical), income_low_week: Math.round(f.income.low),
  risk: risk ? { week_start: risk.week, month: monthOf(risk.firstDay), first_short_day: risk.firstDay, shortfall: risk.shortfall, reason: risk.reason, bills: (risk.bills || []).map(billAmount), fix: risk.fix } : null,
  OPTIONS: Object.fromEntries(Object.entries(OPTIONS).map(([k, o]) => [k, { id: o.id, title: o.title, effect: o.effect }])), signposts: SIGNPOSTS };
const msgs = Array.isArray(body.messages) ? body.messages : [];
const lastUser = [...msgs].reverse().find(m => m.role === 'user');
const userText = (lastUser && (lastUser.content || lastUser.text)) || (body.input && body.input.text) || body.text || '';
const history = msgs.slice(0, lastUser ? msgs.lastIndexOf(lastUser) : msgs.length).slice(-6).map(m => ({ role: m.role === 'user' ? 'user' : 'assistant', content: String(m.content || m.text || '') })).filter(m => m.content);
while (history.length && history[0].role !== 'user') history.shift();
const fill = (s) => s.split('{language}').join(language).split('{name}').join(name).split('{today}').join(f.today).split('{month}').join(facts.risk ? facts.risk.month : 'the coming weeks');
const messages = [...history, { role: 'user', content: 'FACTS: ' + JSON.stringify(facts) + '\n\nUSER SAID: ' + (userText || '(nothing)') }];
const fixed = []; for (const m of messages) { if (fixed.length && fixed[fixed.length - 1].role === m.role) fixed[fixed.length - 1].content += '\n' + m.content; else fixed.push({ ...m }); }
return [{ json: { facts, options_full: OPTIONS, user_transcript: userText, language,
  anthropic_body: { model: 'claude-haiku-5-5', max_tokens: 1024, thinking: { type: 'disabled' }, system: fill("You are \"Future You\", a friendly AI money coach inside a budgeting app for people on irregular incomes and people new to the UK. You are an AI and say so if asked. You are NOT a regulated financial adviser.\n\nRespond in the language with code {language}. Use Modern Standard Arabic for \"ar\". The user is {name}; in Arabic use masculine forms for Adam. Also return an English version for subtitles.\n\nDATES: Today is {today}. The short period starts in {month} (FACTS.risk). Say \"in {month}\", never \"next week\".\n\nINPUT: FACTS (forecast, risk, OPTIONS with pre-computed effects, signposts) and the conversation so far. The user may have spoken; their words were transcribed and may contain errors.\n\nRULES\n1. Numbers: use ONLY figures in FACTS. Never do maths. If the user asks about an option not in OPTIONS, say you can't calculate that yet and suggest talking to a free adviser.\n2. Reply in at most 3 short sentences (max 60 words), spoken style, reading age 9. One idea per sentence. Ask at most one question.\n3. Suggest only actions from OPTIONS. Explain why each helps in one sentence.\n4. Always include at least one signpost id from FACTS.signposts in \"signpost_ids\".\n5. Never recommend borrowing, credit cards, payday loans, Buy Now Pay Later, investments or specific providers. Never say \"guaranteed\" or \"you will\". Use \"the forecast suggests\".\n6. Non-judgemental: never comment on spending choices, money sent to family, religion or culture. Sending money home is a fixed commitment, not a problem to cut.\n7. If the user mentions not affording food or rent now, threats from creditors, gambling harm, or feeling hopeless or unsafe: set \"escalate\": true, reply with care, and point to free help (Citizens Advice, StepChange; Samaritans on 116 123 for emotional crisis). Do not continue budgeting advice in that turn.\n8. If you did not understand the transcript, say so kindly and ask them to repeat.\n9. Never ask for passwords, card numbers or bank login details.\n\nOUTPUT JSON only, no code fences:\n{\"reply_text\": \"...in {language}...\", \"reply_en\": \"...\", \"option_ids\": [\"save_weekly\"], \"signpost_ids\": [\"stepchange\"], \"escalate\": false}"), messages: fixed } } }];

const b = $('Build FACTS').first().json;
const facts = b.facts, OPT = b.options_full;
const textBlock = ($input.first().json.content || []).find(x => x.type === 'text') || {};
let out = null;
try { out = JSON.parse((textBlock.text || '').replace(/^\s*```(json)?/, '').replace(/```\s*$/, '')); } catch (e) { out = null; }
const allowed = new Set((JSON.stringify(facts).match(/\d+/g) || []).map(n => String(parseInt(n, 10))));
const used = ((out && out.reply_en) || '').match(/£\s?(\d+)/g) || [];
const bad = used.some(m => !allowed.has(m.replace(/\D/g, '')));
let reason = null;
if (!out || !out.reply_text || bad) {
  reason = !out ? 'unparseable' : 'invented_number';
  const fb = { en: 'Sorry, I could not work that out safely. The forecast shows a hard few weeks coming. Citizens Advice and StepChange can help for free.',
               ar: 'عذرًا، لم أستطع الإجابة بدقة. التوقعات تُظهر أسابيع صعبة قادمة. منظمة Citizens Advice و StepChange تساعدان مجانًا.' };
  out = { reply_text: fb[b.language] || fb.en, reply_en: fb.en, option_ids: [], signpost_ids: ['citizens_advice', 'stepchange'], escalate: false };
}
let sig = (out.signpost_ids || []).filter(id => facts.signposts[id]);
if (out.escalate) sig = ['citizens_advice', 'stepchange', ...sig];
if (!sig.length) sig = ['citizens_advice'];
const ids = (out.option_ids || []).filter(id => OPT[id]);
const plan = ids.map(id => ({ id, title: OPT[id].title, effect: OPT[id].effect }));
const apply = ids.map(id => OPT[id].apply).filter(Boolean);
const forecastOptions = apply.length ? { billChanges: Object.assign({}, ...apply.map(a => a.billChanges || {})) } : null;
return [{ json: {
  text: out.reply_text, text_en: out.reply_en, audio: null, language: b.language,
  user_transcript: b.user_transcript, plan, forecast_options: forecastOptions,
  signposts: [...new Set(sig)].map(id => facts.signposts[id]),
  escalate: !!out.escalate, guarded: !!reason, guard_reason: reason,
  disclaimer: 'AI coach. Not regulated financial advice.'
} }];
